contracts.definition:
case 'session.abortHandoff':
  const { sessionId } = msg.payload
  const hs = this.ctx.handoffService
  if (!hs) sendError('handoff_unsupported')
  try { await hs.abortHandoff(sessionId); broadcast handoffAborted{sessionId}; reply message.status{aborted} }
  catch { sendError('handoff_failed') }

